<script setup lang="ts">import {ref} from 'vue';import {login} from '../auth/authApi';const identifier=ref('');const password=ref('');const message=ref('');const emit=defineEmits<{done:[]}>();async function submit(){try{await login(identifier.value,password.value);emit('done')}catch{message.value='账号或密码错误'}}</script><template><form class="auth-form" @submit.prevent="submit"><h2>登录</h2><input v-model="identifier" placeholder="手机号或邮箱" autocomplete="username"><input v-model="password" type="password" placeholder="密码" autocomplete="current-password"><p v-if="message" class="error">{{message}}</p><button class="primary-btn">登录</button></form></template>
